import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CuR1irRm.js";var i=JSON.parse(`{"title":"AI service","description":"","frontmatter":{"authorship":["ai"]},"headers":[],"relativePath":"services/ai/index.md","filePath":"services/ai/index.md"}`),a={name:`services/ai/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794666394000`},[...i[0]||=[e(`<h1 id="ai-service" tabindex="-1">AI service <a class="header-anchor" href="#ai-service" aria-label="Permalink to “AI service”">​</a></h1><p>The AI service powers Notopia&#39;s workspace assistant and the AI commands inside the note editor. It runs as the NestJS application <code>apps/ai</code> (Nx project <code>ai</code>, local port <code>8086</code>). AI uses service digit <strong>6</strong>: HTTP and health share <code>8086</code>, and its Redis host port is <code>6376</code>. AI has no PostgreSQL database. Container-internal Redis still listens on its standard <code>6379</code>. It connects a language model to Notopia&#39;s authorized note tools. The model provider supplies text generation; Notopia supplies workspace permissions, note access, editing and usage limits.</p><p>For provider credentials and examples, see <a href="./model-providers.html">OpenRouter and OpenCode</a>.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span>Browser assistant / BlockNote editor</span></span>
<span class="line"><span>    -&gt; Traefik (Authentik JWT validation)</span></span>
<span class="line"><span>    -&gt; AI service (validation, permissions, quota, tool loop)</span></span>
<span class="line"><span>        -&gt; OpenAI-compatible model provider</span></span>
<span class="line"><span>        -&gt; note + authorization + billing (gRPC)</span></span>
<span class="line"><span>        -&gt; Meilisearch (committed note content)</span></span>
<span class="line"><span>        -&gt; Redis (usage, stream leases, continuation state)</span></span>
<span class="line"><span>    &lt;- AI SDK UI-message stream (SSE)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Editing tool -&gt; browser BlockNote editor -&gt; Hocuspocus document session</span></span>
<span class="line"><span>             -&gt; Accept / Discard -&gt; Commit</span></span></code></pre></div><p>The service has no application database or Kafka consumer. Redis is shared state, not an optional cache. It must be persistent, standalone Redis 6.2+ with <code>noeviction</code>; the multi-key Lua operations do not support Redis Cluster.</p><table tabindex="0"><thead><tr><th>Dependency</th><th>Responsibility</th></tr></thead><tbody><tr><td>Note gRPC</td><td>Resolve note metadata and its workspace using the requesting user</td></tr><tr><td>Authorization gRPC</td><td>Discover workspaces and check current read/write access</td></tr><tr><td>Billing gRPC</td><td>Resolve the workspace&#39;s <code>ai_credits_monthly</code> allowance</td></tr><tr><td>Meilisearch</td><td>Search and read bounded, indexed content from committed notes</td></tr><tr><td>AI Redis</td><td>Atomically reserve credits, deduplicate prompts, throttle requests and store assistant tasks</td></tr><tr><td>Document/Hocuspocus</td><td>Authorize and synchronize the browser&#39;s live editing session</td></tr></tbody></table><h3 id="search-editing-and-persistence" tabindex="-1">Search, editing and persistence <a class="header-anchor" href="#search-editing-and-persistence" aria-label="Permalink to “Search, editing and persistence”">​</a></h3><p>Server tools include <code>searchNotes</code>, <code>getNote</code>, <code>getNoteWorkspace</code>, <code>readIndexedNoteContent</code> and, for general chat, <code>listWorkspaces</code>. They recheck access and exclude unavailable, trashed or out-of-workspace notes. Search results describe committed content and can lag behind unsaved editor changes.</p><p>The workspace assistant can use <code>openNoteForEditing</code> to open one existing note beside the chat. After server authorization, the browser waits for an authenticated, synchronized document session before supplying live document state and the supported BlockNote <code>applyDocumentOperations</code> tool. Other notes can be references; one task cannot switch its editing target or edit multiple notes.</p><p>Suggested changes use a fork of the collaborative Yjs document. <strong>Accept</strong> merges the AI changes; <strong>Discard</strong> drops them while preserving collaborator changes. <strong>Commit</strong> is a separate action that creates a revision and makes content available to indexing. Accepting suggestions alone is not a commit; automatic commits depend on the workspace&#39;s plan/settings.</p><h2 id="http-contract" tabindex="-1">HTTP contract <a class="header-anchor" href="#http-contract" aria-label="Permalink to “HTTP contract”">​</a></h2><p><code>POST /ai</code> accepts AI SDK UI messages, not OpenAI Chat Completions messages. The browser uses the shared UI transport directly through Traefik; there is no Next.js AI proxy.</p><table tabindex="0"><thead><tr><th>Request</th><th>Purpose</th></tr></thead><tbody><tr><td><code>messages</code> with <code>workspaceId</code> or <code>noteId</code></td><td>Start normal chat or an editor generation</td></tr><tr><td>Same fields plus <code>assistantMode: true</code></td><td>Start a bounded workspace assistant task</td></tr><tr><td><code>action: &#39;continue&#39;</code>, task/token and expected tool results</td><td>Resume that task after browser work</td></tr><tr><td><code>action: &#39;cancel&#39;</code>, workspace/task IDs</td><td>Invalidate the task; returns <code>204</code></td></tr></tbody></table><p>Initial requests end with a nonempty user prompt and a unique message ID. Workspace context may also come from <code>X-Workspace-Id</code>; conflicting contexts are rejected. If no context is supplied, the user must have exactly one accessible workspace.</p><p>Assistant continuations use one-shot Redis tokens bound to the task owner, workspace and expected calls. The server retains the authoritative transcript; clients cannot replace history on continuation. Continuations retain the original timeout and cumulative step budget.</p><p>Traefik validates the user&#39;s JWT and injects <code>x-forwarded-id</code>. The service trusts that gateway header, so public requests must go through Traefik. A model-provider API key is outbound authentication to the model, not a Notopia user credential.</p><h2 id="credits-and-limits" tabindex="-1">Credits and limits <a class="header-anchor" href="#credits-and-limits" aria-label="Permalink to “Credits and limits”">​</a></h2><p>Billing owns the subscription. AI reads its allowance when admitting an initial generation; continuations of that assistant task do not fetch billing again or debit another monthly credit.</p><ul><li>One started generation/task costs one Notopia credit, including its tool steps and continuations.</li><li>Usage resets at the start of each UTC calendar month, independently of subscription renewal.</li><li>Cancellation or failure before generation starts can refund the reservation. After start, cancellation, provider failure and timeout retain the charge.</li><li>Zero allowance prevents generation; <code>-1</code> means unlimited. Default plans currently give Free no AI credits and Plus/Pro an allowance, but runtime enforcement uses billing&#39;s values.</li><li>OpenRouter/OpenCode charges and Notopia credits are separate. A free provider model does not remove Notopia&#39;s workspace allowance check.</li></ul><table tabindex="0"><thead><tr><th>Environment variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>NOTOPIA_AI_REQUESTS_PER_MINUTE</code></td><td><code>20</code></td><td>Per-user request rate limit</td></tr><tr><td><code>NOTOPIA_AI_CONCURRENT_STREAMS</code></td><td><code>2</code></td><td>Per-user active stream limit</td></tr><tr><td><code>NOTOPIA_AI_TIMEOUT_MS</code></td><td><code>120000</code></td><td>Bounded request/task lifetime</td></tr><tr><td><code>NOTOPIA_AI_MAX_OUTPUT_TOKENS</code></td><td><code>4096</code></td><td>Output budget per model step</td></tr><tr><td><code>NOTOPIA_AI_MAX_STEPS</code></td><td><code>10</code></td><td>Model-step budget, cumulative across a task</td></tr></tbody></table><h2 id="local-setup" tabindex="-1">Local setup <a class="header-anchor" href="#local-setup" aria-label="Permalink to “Local setup”">​</a></h2><p>Run commands from the repository root. Follow the project&#39;s normal local infrastructure, Authentik and database setup first. Compose runs infrastructure; Nx runs application services.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">docker</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> compose</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> deploy/compose/compose.yaml</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> up</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -d</span></span></code></pre></div><p>This includes <code>ai_redis</code> on <code>127.0.0.1:6376</code>, matching <code>apps/ai/.env</code>. Its AOF and named volume preserve usage counters across container recreation. To start only AI Redis:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">docker</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> compose</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> deploy/compose/compose.yaml</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> up</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -d</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --wait</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai_redis</span></span></code></pre></div><p>Choose a <a href="./model-providers.html">model provider</a> and put overrides in <code>apps/ai/.env.local</code>. Nx loads the project environment files. Restart AI after changing them. The checked-in <code>apps/ai/.env</code> also defines these local dependencies:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Local value</th></tr></thead><tbody><tr><td><code>NOTOPIA_AI_SERVICES_NOTE_GRPC_URL</code></td><td><code>127.0.0.1:18081</code></td></tr><tr><td><code>NOTOPIA_AI_SERVICES_AUTHORIZATION_GRPC_URL</code></td><td><code>127.0.0.1:18089</code></td></tr><tr><td><code>NOTOPIA_AI_SERVICES_BILLING_GRPC_URL</code></td><td><code>127.0.0.1:18084</code></td></tr><tr><td><code>NOTOPIA_AI_MEILI_HOST</code></td><td><code>http://meilisearch.notopia.localhost</code></td></tr><tr><td><code>NOTOPIA_AI_MEILI_API_KEY</code></td><td>Local Meilisearch development key</td></tr><tr><td><code>NOTOPIA_AI_REDIS_URL</code></td><td><code>redis://127.0.0.1:6376</code></td></tr></tbody></table><p>Use a workspace with a billing allowance. On a prepared development database, <code>just fixtures-billing</code> creates a fake Pro lifetime subscription for workspace <code>00000000-0000-4000-8000-000000000110</code>. It requires billing migrations and seeded prices (<code>just seed-billing</code>), which in turn require the billing service&#39;s Stripe sandbox configuration. The note and authorization fixtures must also give your user access to that workspace. Fake billing provider IDs support entitlement testing, not real checkout or refunds.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> run-many</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -t</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> run</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -p</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> note,authorization,billing,document,search-worker,ai</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --parallel=6</span></span></code></pre></div><p>In another terminal:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> dev</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> web</span></span></code></pre></div><p>Open <code>http://web.notopia.localhost</code>, sign in and open the workspace assistant. Ask it to find and summarize a note, then ask it to edit that note. Check the opened target, review the suggestions, Accept or Discard, and Commit accepted changes. Test the editor&#39;s inline AI too.</p><h3 id="health-and-troubleshooting" tabindex="-1">Health and troubleshooting <a class="header-anchor" href="#health-and-troubleshooting" aria-label="Permalink to “Health and troubleshooting”">​</a></h3><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> http://api.notopia.localhost/ai/health/ready</span></span></code></pre></div><p><code>/ai/health/live</code> (also <code>/ai/health</code>) and <code>/ai/health/startup</code> report that the HTTP service is running; <code>/ai/health/ready</code> pings Redis. Readiness does not prove that model credentials, other gRPC services or browser document editing work.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td><code>402 planLimitExceeded</code></td><td>Workspace billing allowance and remaining Notopia credits</td></tr><tr><td><code>429</code></td><td>Per-user rate/concurrency limits; honor <code>Retry-After</code></td></tr><tr><td><code>503 aiUsageUnavailable</code></td><td>Redis address, connectivity and persistence configuration</td></tr><tr><td><code>503 billingServiceUnavailable</code></td><td>Billing gRPC and valid plan allowance data</td></tr><tr><td>Provider authentication/model error</td><td>Provider base URL, key, model ID and account access</td></tr><tr><td>Text works but note tools fail</td><td>Model support for streamed tool calls and structured tool input</td></tr><tr><td>Note opens but editing fails</td><td>Document logs, WebSocket authentication, schema and synchronization</td></tr><tr><td>Search shows old content</td><td>Commit the note and check search-worker indexing</td></tr></tbody></table><p>Before streaming, failures are JSON errors. After streaming starts, failures appear as safe AI SDK stream error parts; HTTP <code>200</code> alone does not prove a generation succeeded.</p><h2 id="development-checks" tabindex="-1">Development checks <a class="header-anchor" href="#development-checks" aria-label="Permalink to “Development checks”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> test</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> typecheck</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lint</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --fix</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> build</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai</span></span></code></pre></div><p>Real Redis tests require a separate disposable Redis, not the instance holding manual-test credits. Without the variable below, those integration cases are skipped:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">AI_TEST_REDIS_URL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">redis://127.0.0.1:16385</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> nx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> test</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skip-nx-cache</span></span></code></pre></div><p>Implementation guidance lives in <code>apps/ai/AGENTS.md</code> and <code>apps/ai/HOW_TO_ADD_TOOLS.md</code>. The internal walkthrough <code>docs/ai/ASSISTANT_NOTE_EDITING.md</code> covers the continuation protocol, shared browser runner and deterministic collaborative-editor fixture in more detail.</p>`,43)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};